const items = $input.first().json.results || [];

if (items.length === 0) {
  return [];
}

let taskCards = [];
let emailList = [];

for (const item of items) {
  const props = item.properties || {};
  const title = (props['Task Name']?.title || []).map(t => t.plain_text).join('') || 'Untitled Task';
  const priority = props['Priority']?.select?.name || 'P2 - High';
  const score = props['Priority Score']?.formula?.number || 0;
  const escalation = props['Escalation Level']?.formula?.string || '⚠️ ELEVATED';
  const dueDate = props['Due Date']?.date?.start || 'No date set';
  const endDate = props['End Date']?.date?.start || dueDate;
  const url = item.url || `https://notion.so/${item.id.replace(/-/g, '')}`;
  const team = props['Team / Pod']?.select?.name || 'General';
  const complexity = props['Complexity']?.select?.name || '⭐ 3';

  taskCards.push({
    title,
    priority,
    score,
    escalation,
    dueDate,
    endDate,
    team,
    complexity,
    url
  });

  emailList.push(`• [${priority}] <b>${title}</b> (Score: ${score} | Sizing: ${complexity}) | Pod: ${team} | Target End: ${endDate} — <a href="${url}">Open in Notion</a>`);
}

// Construct Google Chat Card v2 Payload
const widgets = [
  {
    textParagraph: {
      text: `<b>🚨 Action Required:</b> Detected <b>${taskCards.length} critical / high-urgency tasks</b> requiring team attention today.`
    }
  }
];

for (const t of taskCards.slice(0, 5)) {
  widgets.push({
    decoratedText: {
      topLabel: `${t.escalation} | ${t.priority} (Score: ${t.score})`,
      text: `<b>${t.title}</b>`,
      bottomLabel: `Team: ${t.team} | Complexity: ${t.complexity} | Cutoff: ${t.endDate}`,
      button: {
        text: 'OPEN TASK',
        onClick: {
          openLink: {
            url: t.url
          }
        }
      }
    }
  });
}

const googleChatPayload = {
  cardsV2: [
    {
      cardId: 'wasp_critical_escalations_' + Date.now(),
      card: {
        header: {
          title: '🐝 WASP Engine — Critical Escalation Alert',
          subtitle: `${taskCards.length} Tasks Exceeding Urgency Threshold`,
          imageUrl: 'https://cdn-icons-png.flaticon.com/512/564/564619.png',
          imageType: 'CIRCLE'
        },
        sections: [
          {
            header: 'Top Escalated & High-Urgency Deliverables',
            widgets: widgets
          }
        ]
      }
    }
  ]
};

const emailHtml = `
<h2>🐝 WASP Engine: Daily Escalation Report</h2>
<p>There are <b>${taskCards.length} high-urgency or overdue tasks</b> in your WASP Dashboard today:</p>
<ul>
  ${emailList.join('<br>')}
</ul>
<p><a href="https://app.notion.com/p/WASP-Dashboard-Work-Analysis-System-Profile-Dashboard-3fff1bcff9b88188b004f044be8090fe" style="background:#2383e2;color:#fff;padding:8px 16px;text-decoration:none;border-radius:4px;font-weight:bold;">Open WASP Dashboard</a></p>
`;

return [{
  json: {
    count: taskCards.length,
    googleChatPayload,
    emailHtml,
    subject: `🚨 [WASP] ${taskCards.length} Critical Tasks Require Immediate Action Today`
  }
}];
